CREATE OR REPLACE FUNCTION public.vip_create_invite(p_programme uuid, p_label text DEFAULT NULL::text, p_max_uses integer DEFAULT NULL::integer, p_days integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_token text;
begin
  if not public.vip_can_manage(p_programme) then raise exception 'Only the market lead or the team can make a VIP link.'; end if;
